/**
 * @suppress
 */
public object FfiConverterTypeMatch: FfiConverter<Match, Pointer> {

    override fun lower(value: Match): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): Match {
        return Match(value)
    }

    override fun read(buf: ByteBuffer): Match {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: Match) = 8UL

    override fun write(value: Match, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



data class GarbageEntry (
    var `lines`: kotlin.UInt, 
    var `active`: kotlin.Boolean
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeGarbageEntry: FfiConverterRustBuffer<GarbageEntry> {
    override fun read(buf: ByteBuffer): GarbageEntry {
        return GarbageEntry(
            FfiConverterUInt.read(buf),
            FfiConverterBoolean.read(buf),
        )
    }

    override fun allocationSize(value: GarbageEntry) = (
