    GARBAGE,
    I,
    O,
    T,
    L,
    J,
    S,
    Z;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeCellKind: FfiConverterRustBuffer<CellKind> {
    override fun read(buf: ByteBuffer) = try {
        CellKind.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: CellKind) = 4UL

    override fun write(value: CellKind, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}






