/**
 * @suppress
 */
public object FfiConverterSequenceTypeGarbageEntry: FfiConverterRustBuffer<List<GarbageEntry>> {
    override fun read(buf: ByteBuffer): List<GarbageEntry> {
        val len = buf.getInt()
        return List<GarbageEntry>(len) {
            FfiConverterTypeGarbageEntry.read(buf)
        }
    }

    override fun allocationSize(value: List<GarbageEntry>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterTypeGarbageEntry.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<GarbageEntry>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeGarbageEntry.write(it, buf)
        }
    }
}




